import {formFor} from './tierlist-model.mjs';
const name=f=>typeof f.name==='string'?f.name:f.name.en||f.name.zh;
export async function drawTierlist(canvas,state,units){const width=1000,tile=68,cols=12,heights=state.rows.map(r=>Math.max(90,Math.ceil(r.units.length/cols)*tile+16));canvas.width=width;canvas.height=110+heights.reduce((a,b)=>a+b,0)+70;const ctx=canvas.getContext('2d');await document.fonts.ready;ctx.fillStyle='#fffef1';ctx.fillRect(0,0,width,canvas.height);ctx.fillStyle='#282625';ctx.font='600 28px Poppins';ctx.fillText(state.title.slice(0,55),24,43);ctx.font='16px Poppins';ctx.fillText(state.gameMode+' · Tier '+state.tier+' (highest available for lower-tier families)',24,77);let y=110;for(const [i,row] of state.rows.entries()){ctx.fillStyle=row.color;ctx.fillRect(0,y,130,heights[i]);ctx.fillStyle='#282625';ctx.font='600 20px Poppins';ctx.fillText(row.label.slice(0,10),12,y+heights[i]/2+7);ctx.strokeStyle='#d6c6a3';ctx.strokeRect(130,y,width-130,heights[i]);for(const [j,id] of row.units.entries()){const unit=units.find(u=>u.id===id);if(!unit)continue;const form=formFor(unit,state.tier),img=new Image();img.src=new URL('./tatari-data/'+form.playerhead,import.meta.url);try{await img.decode();ctx.drawImage(img,145+(j%cols)*tile,y+8+Math.floor(j/cols)*tile,48,48)}catch{throw Error("Could not load Tatari artwork. Try exporting again.")}ctx.fillStyle='#282625';ctx.font='9px Poppins';ctx.fillText(name(form).slice(0,13),141+(j%cols)*tile,y+66+Math.floor(j/cols)*tile)}y+=heights[i]}ctx.font='13px Poppins';ctx.fillText('Creator opinion · Clash of Critters Unofficial Companion',24,y+36);return canvas}
